CREATE OR REPLACE FUNCTION trip_private.set_adult_cards(p_trip uuid,p_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Captain only'; END IF; INSERT INTO public.trip_adult_settings(trip_id,enabled) VALUES(p_trip,p_enabled) ON CONFLICT(trip_id) DO UPDATE SET enabled=excluded.enabled; END $fn$;
CREATE OR REPLACE FUNCTION trip_private.approve_adult_player(p_trip uuid,p_user uuid,p_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Captain only'; END IF; IF p_approve THEN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_user) OR NOT EXISTS(SELECT 1 FROM public.player_birthdays WHERE user_id=p_user AND birthday <= (current_date - interval '21 years')::date) THEN RAISE EXCEPTION 'Player must be 21 or older'; END IF; INSERT INTO public.trip_adult_approvals(trip_id,user_id,approved_by) VALUES(p_trip,p_user,auth.uid()) ON CONFLICT(trip_id,user_id) DO UPDATE SET approved_by=excluded.approved_by; ELSE DELETE FROM public.trip_adult_approvals WHERE trip_id=p_trip AND user_id=p_user; END IF; END $fn$;
CREATE OR REPLACE FUNCTION trip_private.use_item_alternative(p_trip uuid,p_date date,p_kind text,p_index integer,p_alternative text,p_group boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_captain uuid; v_user uuid; BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not a member'; END IF; IF p_date NOT BETWEEN (SELECT start_date FROM public.trips WHERE id=p_trip) AND (SELECT end_date FROM public.trips WHERE id=p_trip) OR p_kind NOT IN ('bingo','quest','trivia') OR p_index NOT BETWEEN 0 AND 8 OR length(trim(p_alternative)) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Invalid alternative'; END IF; SELECT user_id INTO v_captain FROM public.trip_members WHERE trip_id=p_trip AND role='captain' LIMIT 1; IF p_group AND NOT (auth.uid()=v_captain OR EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND host_id=auth.uid() AND starts_at::date=p_date)) THEN RAISE EXCEPTION 'Host or Captain only'; END IF; v_user:=CASE WHEN p_group THEN v_captain ELSE auth.uid() END; INSERT INTO public.trip_item_alternatives(trip_id,day_date,kind,item_index,user_id,alternative) VALUES(p_trip,p_date,p_kind,p_index,v_user,trim(p_alternative)) ON CONFLICT(trip_id,day_date,kind,item_index,user_id) DO UPDATE SET alternative=excluded.alternative; END $fn$;
CREATE OR REPLACE FUNCTION trip_private.start_game_turns(p_trip uuid,p_week integer,p_cards integer,p_random boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_order uuid[]; BEGIN IF NOT trip_private.can_run_turns(p_trip,p_week) THEN RAISE EXCEPTION 'Host or leader only'; END IF; IF p_cards NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Choose 1 to 5 cards'; END IF; SELECT array_agg(user_id ORDER BY CASE WHEN p_random THEN random() ELSE 0 END,joined_at,user_id) INTO v_order FROM public.trip_members WHERE trip_id=p_trip; IF cardinality(v_order)<1 THEN RAISE EXCEPTION 'No players'; END IF; INSERT INTO public.game_night_turns(trip_id,week_number,cards_per_person,player_order,turn_index,card_number,active) VALUES(p_trip,p_week,p_cards,v_order,0,1,true) ON CONFLICT(trip_id) DO UPDATE SET week_number=excluded.week_number,cards_per_person=excluded.cards_per_person,player_order=excluded.player_order,turn_index=0,card_number=1,active=true; END $fn$;
CREATE OR REPLACE FUNCTION trip_private.next_game_turn(p_trip uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v public.game_night_turns; BEGIN SELECT * INTO v FROM public.game_night_turns WHERE trip_id=p_trip FOR UPDATE; IF NOT FOUND OR NOT v.active THEN RAISE EXCEPTION 'No active round'; END IF; IF NOT trip_private.can_run_turns(p_trip,v.week_number) THEN RAISE EXCEPTION 'Host or leader only'; END IF; IF v.turn_index+1 >= cardinality(v.player_order) THEN IF v.card_number>=v.cards_per_person THEN UPDATE public.game_night_turns SET active=false WHERE trip_id=p_trip; ELSE UPDATE public.game_night_turns SET turn_index=0,card_number=card_number+1 WHERE trip_id=p_trip; END IF; ELSE UPDATE public.game_night_turns SET turn_index=turn_index+1 WHERE trip_id=p_trip; END IF; END $fn$;
CREATE OR REPLACE FUNCTION public.set_adult_cards(p_trip uuid,p_enabled boolean) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $fn$ SELECT trip_private.set_adult_cards(p_trip,p_enabled) $fn$;
CREATE OR REPLACE FUNCTION public.approve_adult_player(p_trip uuid,p_user uuid,p_approve boolean) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $fn$ SELECT trip_private.approve_adult_player(p_trip,p_user,p_approve) $fn$;
CREATE OR REPLACE FUNCTION public.use_item_alternative(p_trip uuid,p_date date,p_kind text,p_index integer,p_alternative text,p_group boolean DEFAULT false) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $fn$ SELECT trip_private.use_item_alternative(p_trip,p_date,p_kind,p_index,p_alternative,p_group) $fn$;
CREATE OR REPLACE FUNCTION public.start_game_turns(p_trip uuid,p_week integer,p_cards integer,p_random boolean) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $fn$ SELECT trip_private.start_game_turns(p_trip,p_week,p_cards,p_random) $fn$;
CREATE OR REPLACE FUNCTION public.next_game_turn(p_trip uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $fn$ SELECT trip_private.next_game_turn(p_trip) $fn$;
REVOKE ALL ON FUNCTION public.set_adult_cards(uuid,boolean),public.approve_adult_player(uuid,uuid,boolean),public.use_item_alternative(uuid,date,text,integer,text,boolean),public.start_game_turns(uuid,integer,integer,boolean),public.next_game_turn(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_adult_cards(uuid,boolean),public.approve_adult_player(uuid,uuid,boolean),public.use_item_alternative(uuid,date,text,integer,text,boolean),public.start_game_turns(uuid,integer,integer,boolean),public.next_game_turn(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION trip_private.set_adult_cards(uuid,boolean),trip_private.approve_adult_player(uuid,uuid,boolean),trip_private.use_item_alternative(uuid,date,text,integer,text,boolean),trip_private.start_game_turns(uuid,integer,integer,boolean),trip_private.next_game_turn(uuid) TO authenticated;